void nexus_register_bionic_symbols(void) {
    // Ensure all symbols are pulled from the static archives.
    reference_bionic_symbols();
    nexus_loader_add_symbols(g_bionic_symbols,
                             sizeof(g_bionic_symbols) / sizeof(g_bionic_symbols[0]));
}
